const d = $('Load All Project Data').first().json;
const dbPrompt = $input.first().json;

const briefing = typeof d.briefing === 'string' ? JSON.parse(d.briefing) : (d.briefing || {});
const design = typeof d.design_option === 'string' ? JSON.parse(d.design_option) : (d.design_option || {});
const costs = typeof d.cost_estimate === 'string' ? JSON.parse(d.cost_estimate) : (d.cost_estimate || {});
const plan = typeof d.project_plan === 'string' ? JSON.parse(d.project_plan) : (d.project_plan || {});
const trades = Array.isArray(d.trade_assignments) ? d.trade_assignments : [];
const materials = Array.isArray(d.approved_materials) ? d.approved_materials : [];
const intel = Array.isArray(d.intelligence_entries) ? d.intelligence_entries : [];
const breakdown = Array.isArray(costs.breakdown) ? costs.breakdown : [];

const tradesSummary = trades.map(t => `${t.trade_type || t.specialty}: ${t.scope_description ? t.scope_description.substring(0, 60) : '?'}`).join(', ');
const materialsSummary = materials.slice(0, 10).map(m => `${m.category}: ${m.name} (${m.brand || 'sin marca'}, ${m.quality_tier || '?'})`).join('; ');
const partidas = breakdown.slice(0, 10).map(p => `${p.partida || p.description}: ${p.importe || p.amount || '?'}€`).join('; ');

const prompt_system_fallback = `Eres un arquitecto técnico experto en reformas de vivienda en España.
Analizas proyectos completados para extraer conocimiento reutilizable en futuros proyectos similares.
Devuelve ÚNICAMENTE un JSON válido, sin texto adicional.

Estructura exacta requerida:
{
  "summary": string (resumen de 2-3 líneas del proyecto y su alcance),
  "scope_summary": string (descripción técnica del alcance: qué habitaciones, qué trabajos),
  "decisions_made": [
    {"decision": string, "rationale": string, "impact": string}
  ],
  "lessons_learned": [
    {"lesson": string, "category": "presupuesto|normativa|diseño|gremios|materiales|plazos", "importance": "alta|media|baja"}
  ],
  "patterns": [
    {"pattern": string, "category": "presupuesto|normativa|diseño|gremios|materiales", "description": string}
  ],
  "tags": string[]
}

Instrucciones:
- Las decisiones_made deben reflejar las elecciones clave del proyecto (opción de diseño, materiales destacados, soluciones técnicas)
- Los lessons_learned deben ser patrones útiles para proyectos futuros (riesgos, oportunidades, estimaciones)
- Los patterns son tendencias observables en este tipo de proyecto/zona
- Las tags son palabras clave para búsquedas futuras (tipo reforma, zona, complejidad, gremios, etc.)`;
// === STUDIO PROFILE INJECTION (B24) ===
const _studio = $('Load Studio Profile').first().json || {};
function _safeStudio(v){ if(v==null)return null; if(typeof v==='string'){try{return JSON.parse(v);}catch(e){return v;}} return v; }
const _id=_safeStudio(_studio.identity)||{},_priorities=_safeStudio(_studio.priorities)||[];
const _SP_MEM_LINES=[];
_SP_MEM_LINES.push('Estudio: '+(_id.nombre_estudio||'estudio')+' en '+(_id.ciudad||'Espana')+'.');
_SP_MEM_LINES.push('PRIORIDADES del estudio (extrae lessons_learned coherentes con estas):');
(_priorities||[]).forEach(p=>_SP_MEM_LINES.push((p.orden||'?')+'. '+(p.prioridad||'')));
const _SP_MEM=_SP_MEM_LINES.join('\n');
// === END STUDIO PROFILE INJECTION ===
const prompt_system = _SP_MEM + '\n\n' + ((dbPrompt && dbPrompt.content) ? dbPrompt.content : prompt_system_fallback);  

const prompt_user = `PROYECTO: ${d.project_name}
Tipo: ${d.project_type} | Propiedad: ${d.property_type} | Área: ${d.property_area_m2} m²
Ubicación: ${d.location_city}, ${d.location_province}
Presupuesto estimado: ${costs.total_estimated || '?'}€
Duración planificada: ${plan.total_duration_days ? Math.round(plan.total_duration_days / 7) + ' semanas' : '?'}

OPCIÓN DE DISEÑO ELEGIDA: ${design.title || design.option_name || 'No especificada'}
${design.description ? 'Descripción: ' + design.description : ''}

GREMIOS Y COSTES: ${tradesSummary || 'No disponible'}

PRINCIPALES PARTIDAS: ${partidas || 'No disponible'}

MATERIALES APROBADOS: ${materialsSummary || 'No disponible'}

CONTEXTO ADICIONAL (project_intelligence):
${intel.slice(0, 5).map(i => `[${i.agent_name}/${i.key}]: ${JSON.stringify(i.value).substring(0, 200)}`).join('\n') || 'Sin intel adicional'}

Extrae el conocimiento clave de este proyecto en JSON.`;

return [{
  json: {
    ...d,
    cost_estimated: costs.total_estimated || null,
    duration_estimated_days: plan.total_duration_days || null,
    trades_used_json: JSON.stringify(trades.map(t => ({trade_type: t.trade_type, scope_description: t.scope_description}))),
    materials_notable_json: JSON.stringify(materials.slice(0, 15)),
    prompt_system,
    prompt_user,
    model: 'gpt-4o',
    temperature: 0.4,
    project_id: d.id,
    agent_name: 'agent_memory'
  }
}];

const project = $('Build Memory Prompt').first().json;
const llm = $input.first().json;
const text = llm.text || '';

let mem = {};
let parse_error = null;

try {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('No JSON found in LLM response');
  mem = JSON.parse(match[0]);
} catch(e) {
  parse_error = e.message;
  mem = {
    summary: project.project_name + ' — ' + project.project_type + ' en ' + project.location_city,
    scope_summary: project.property_area_m2 + ' m², ' + (project.property_type || 'piso'),
    decisions_made: [],
    lessons_learned: [],
    patterns: [],
    tags: [project.project_type, project.location_province || 'esp', project.property_type || 'piso'].filter(Boolean)
  };
}

const tags = Array.isArray(mem.tags) ? mem.tags : [];
if (project.project_type && !tags.includes(project.project_type)) tags.push(project.project_type);
if (project.location_province) tags.push(project.location_province.toLowerCase().replace(/\s+/g, '_'));
if (project.property_type) tags.push(project.property_type);

return [{
  json: {
    project_id: project.id,
    project_type: project.project_type,
    location_zone: project.location_province || project.location_city,
    property_type: project.property_type,
    area_m2: project.property_area_m2,
    cost_estimated: project.cost_estimated,
    duration_estimated_days: project.duration_estimated_days,
    summary: mem.summary || '',
    scope_summary: mem.scope_summary || '',
    decisions_made_json: JSON.stringify(mem.decisions_made || []),
    lessons_learned_json: JSON.stringify(mem.lessons_learned || []),
    patterns_json: JSON.stringify(mem.patterns || []),
    trades_used_json: project.trades_used_json,
    materials_notable_json: project.materials_notable_json,
    tags_array: tags.slice(0, 20),
    parse_error: parse_error || null
  }
}];

const saved = $input.first().json;
const parsed = $('Parse Memory Response').first().json;
const lessons = (parsed.lessons_learned_json) ? JSON.parse(parsed.lessons_learned_json) : [];
const patterns = (parsed.patterns_json) ? JSON.parse(parsed.patterns_json) : [];
const lessonsText = lessons.slice(0, 5).map(l => l.lesson || JSON.stringify(l)).join('. ');
const patternsText = patterns.slice(0, 3).map(p => p.pattern || JSON.stringify(p)).join('. ');
const tags = parsed.tags_array || [];
const parts = [];
if (parsed.project_type) parts.push('Tipo: ' + parsed.project_type);
if (parsed.location_zone) parts.push('Zona: ' + parsed.location_zone);
if (parsed.property_type) parts.push('Inmueble: ' + parsed.property_type);
if (parsed.area_m2) parts.push('Area: ' + parsed.area_m2 + ' m2');
if (parsed.summary) parts.push('Resumen: ' + parsed.summary);
if (parsed.scope_summary) parts.push('Alcance: ' + parsed.scope_summary);
if (lessonsText) parts.push('Lecciones: ' + lessonsText);
if (patternsText) parts.push('Patrones: ' + patternsText);
if (tags.length) parts.push('Tags: ' + tags.join(', '));
const text = parts.join('. ');
return [{ json: { memory_case_id: saved.id, text } }];
